commit 51b8ff23cefb5112937dec9727a5b5d6e913aae6
Author: Miles Malerba <mmalerba@google.com>
Date:   Thu Feb 13 00:26:10 2025 +0000

    support tagged template literals in expressions (#59947)

Adds support for using tagged template literals in Angular templates.

Ex:
```
@Component({
  template: '{{ greet`Hello, ${name()}` }}'
})
export class MyComp {
  name = input();

  greet(strings: TemplateStringsArray, name: string) {
    return strings[0] + name + strings[1] + '!';
  }
}
```

PR Close #59947 name + strings[1] + '!';
      }
    }
    ```

    PR Close #59947

