+
+      env.driveMain();
+
+      const jsContents = env.getContents('test.js');
+      const hmrContents = env.driveHmr('test.ts', 'Cmp');
+
+      expect(jsContents).toContain(`import { Dep } from './dep';`);
+      expect(jsContents).toContain('const Cmp_Defer_1_DepsFn = () => [Dep];');
