+
+          @Component({
+            selector: 'cmp',
+            standalone: true,
+            template: '{{#invalid}}',
+          })
+          export class Cmp {}
+        `,
+      );
+
+      const hmrContents = env.driveHmr('test.ts', 'Cmp');
+      expect(hmrContents).toBe(null);
+    });
