+      immediate: hasHydrateTrigger(blockInfo, DeferBlockTrigger.Immediate),
+      timer: getHydrateTimerTrigger(blockInfo),
+      viewport: hasHydrateTrigger(blockInfo, DeferBlockTrigger.Viewport),
