+describe('microtask effects in TestBed', () => {
+  it('created in the constructor should run with detectChanges()', () => {
+    const log: string[] = [];
+    @Component({
+      selector: 'test-cmp',
+      standalone: true,
+      template: '',
+    })
+    class Cmp {
+      constructor() {
+        log.push('Ctor');
+
+        microtaskEffect(() => {
+          log.push('Effect');
+        });
+      }
+
+      ngDoCheck() {
+        log.push('DoCheck');
+      }
+    }
+
+    TestBed.createComponent(Cmp).detectChanges();
+
