+  eventContract.ecrd((eventInfo: EventInfo, globalDispatch?: boolean) => {
+    return dispatcher.dispatch(eventInfo, globalDispatch);
+  }, Restriction.I_AM_THE_JSACTION_FRAMEWORK);
+}
