+    contentScriptConnected(otherFrameId, 'name2', 'https://angular.dev/');
+    const topLevelFrame = getFrameFromFrameManager(topLevelFrameId);
+    expect(topLevelFrame).toBeDefined();
+    frameManager.inspectFrame(topLevelFrame!);
