+  constructor() {
+    if (!(this._platformNavigation instanceof FakeNavigation)) {
+      throw new Error(
+          'FakePlatformNavigation cannot be used without FakeNavigation. Use ' +
+              '`provideFakeNavigation` to have all these services provided together.',
+      );
+    }
+  }
+
