+    this.window.addEventListener('popstate', fn);
+    return () => this.window.removeEventListener('popstate', fn);
+  }
+
+  onHashChange(fn: LocationChangeListener): VoidFunction {
+    this.window.addEventListener('hashchange', fn as any);
